WFJ.Data.add("gossip", {
  ["4307ee68b64f2233"] = { "Cosa chiedi allo Stormo dei Draghi Blu?", "." },
  ["430d8f2f44d3780b"] = { "Se è corretto, allora ho ancora molte ricerche da fare.", "." },
  ["430f6c6d3583f81e"] = { "Sai chi è davvero intelligente? Nogg! Più intelligente persino di me. Va' a dire a Nogg che ti manda Thund! Lo trovi vicino al pannello di controllo, laggiù.", "." },
  ["43124be26f1d1d7d"] = { "Ogni giorno è una prova, e oggi non fa eccezione. Se superi questa prova, condividerò con te parte del mio sapere...", "." },
  ["4312b432add4bb65"] = { "Hai completato la missione!", "." },
  ["4313d4c31b61ab0f"] = { "Non ce la farò... vai... vai avanti senza di me...", "." },
  ["431f09beeeca0c01"] = { "Quante pelli ha raccolto finora l'⟦Alliance=Alleanza⟧?", "." },
  ["43225cb73ad72c3d"] = { "Mmm... un po' di stoffa ce l'hai, te lo concedo. Bene allora, dove eravamo rimasti?", "." },
  ["43226f92cdc6a218"] = { "Mi spiace, ma non vendo cavalli a chi non sia almeno Amichevole con il Regno di ⟦Stormwind=Roccavento⟧. Questi destrieri sono i migliori che troverai, e di certo non vorremmo che finissero nelle mani dei nostri nemici.\n\nNon dico che tu sia un nemico, ovviamente... guadagnati la fiducia di ⟦Stormwind=Roccavento⟧ e poi potremo fare affari.", "." },
  ["432ada9d62159c27"] = { "Cuccioli insolenti! Vi siete precipitati verso la vostra morte! Guardate, il padrone si desta!", "." },
  ["432d729b444e63a9"] = { "Veniamo al presente: la formula che ne è risultata funziona e permette di creare un drone più controllato; lo svantaggio, però, è che il composto inattivo è estremamente instabile.\n\nGallywix, tutti in questa torre e tutti là fuori sono infettati dal veleno. Ci sta colpendo la mente e il corpo. I nostri organi interni sono diventati molli ed estremamente fragili. Questa è la tua occasione, {name}. Non ho la forza di andare avanti e sento che presto diventerò uno di «loro».", "." },
  ["4331ad48e173d8dd"] = { "Sento odore di {race}.", "." },
  ["433b454991468670"] = { "Gli intrusi hanno violato la covata! Date l'allarme! Proteggete le uova a ogni costo!", "." },
  ["433d11c4f7106238"] = { "Supremo magistro... ho... fallito.", "." },
  ["433dfbac107ce504"] = { "%s piagnucola.", "." },
  ["43425db52bcfef66"] = { "%s rosicchia l'esca avidamente.", "." },
  ["434764915c4df11a"] = { "I nani Granmartello avranno anche destrieri veloci, ma quei grifoni del ⟦Aerie Peak=Picco dell'Aquila⟧ reggerebbero il calore della ⟦Great Forge=Grande Forgia⟧? Non credo proprio!", "." },
  ["4350ef28e07b5d4a"] = { "Benvenut<o/a>, <sacerdote/sacerdotessa>. L'⟦The Eye of Zuldazar=Occhio di Zuldazar⟧ pulsa di energia. Sei pront<o/a> per il passo successivo. Dammi il talismano e compirò l'infusione.", "." },
  ["4352061725627201"] = { "Gli spiriti di ⟦Stonetalon=Petrartiglio⟧ sono ancora in collera, {name}.", "." },
  ["43542d62edf59c2d"] = { "Soldati dei Piccatonante, aiutateci e proteggeteci! Il Signore della Foresta ci ha concesso la sua protezione. Ora il portale deve essere aperto!", "." },
  ["4356812cacf5af2a"] = { "%s russa forte e si accoccola accanto ad A-Me 01.", "." },
  ["4357101097d98707"] = { "Ho troppo da fare per giocare a «indovina l'odore» con te, {race}. Di' cosa vuoi o sparisci dalla mia vista!", "." },
  ["4363f24e0fc620ef"] = { "Non disturbarmi, recluta. Presentati al comandante Cyclas o al sacerdote del cielo Aanders se hai le mani in mano.", "." },
  ["4366e6c07f9643f8"] = { "Jeztor sta venendo a prenderti, Piccatonante!", "." },
  ["437280c13549b9b1"] = { "Ci servono altri lupi! Venite alle stalle ad aiutare!", "." },
  ["4373d0b6ae4ae051"] = { "Sento che hai inflitto innumerevoli morti agli Hakkari, {name}. Porti addosso il fetore del loro mojo.\n\nImmagino che il talismano dell'Ombra ti abbia aiutato nella mattanza? Dammelo e lascia che ne accresca il potere.", "." },
  ["43740eb78425d500"] = { "Il villaggio di Dolanaar, su Teldrassil, è la dimora dell'anziano Bladeleaf.", "." },
  ["437500bc404c8a7d"] = { "%s esce dalla capanna di tronchi e ti sorprende a manomettere le scorte di grano!", "." },
  ["438105ede1ec715b"] = { "Ora dobbiamo aspettare, {name}. Non passerà molto prima che i naga si accorgano di ciò che abbiamo fatto.", "." },
  ["43869d0fcbf631cb"] = { "Tutti i preparativi sono completi, {class}. Aspettiamo che l'ultimo materiale venga spedito a ⟦Silithus=Silitus⟧, il che dovrebbe avvenire in meno di un giorno. Poi, una volta conclusa l'organizzazione laggiù, qualcuno dovrà farsi avanti e suonare il gong sull'Altare dello Scarabeo con lo Scettro delle Sabbie Mutevoli. Allora comincerà la Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Che la Madre Terra vegli su tutti noi, allora.", "." },
  ["4389a2a4e2d5d317"] = { "Sono pezzi davvero belli, {name}. Per la maestria e la cura messe nel farli, si venderebbero a parecchio argento in più di un pezzo qualunque.\n\nHai completato il mio ordine, e con esso arriva la tua ricompensa. La conoscenza per fare le vesti di Cuoio Selvatico ora è tua!", "." },
  ["43912074bf2dc3ba"] = { "Ottimo, cominciamo... ah! Ci sei cascat<o/a>! Non avrai pensato che fosse così semplice. Dovrai dimostrare il tuo valore come tutti gli altri!", "." },
  ["43a7ae12f8f34cec"] = { "Bijou sa dove sono nascosti i tesori.", "." },
  ["43af2d862cf65a11"] = { "Cerchi questi???? Non li avrai mai!", "." },
  ["43b0337ed10f973d"] = { "Conosco la strada, insetto. Non c'è bisogno di pungolarmi come se fossi bestiame.", "." },
  ["43b3d2064662c342"] = { "Lok'tar! Sembra che tu abbia bisogno di aiuto.", "." },
  ["43b44d542ae7db1d"] = { "L'anziano Windrun risiede nella ⟦Crown Guard Tower=Torre della Corona⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "." },
  ["43b4a4be2d3e6a89"] = { "<Un/Una> {class} di nome {name}? Sarai un'ottima colazione!", "." },
  ["43b52babc310c83b"] = { "Resto qui a sorvegliare il relitto. Presto! Speriamo che nessuno noti il fumo...", "." },
  ["43c16414ec2abcef"] = { "L'⟦Alliance=Alleanza⟧ ha preso la ⟦Irondeep Mine=Miniera di Ferrofondo⟧!", "." },
  ["43c17b2623854fd1"] = { "Oh sì. Noi ce l'ha proprio qui.", "." },
  ["43c56166e54e3d17"] = { "Certo che non c'è alcun pericolo che tutto prenda fuoco ed esploda come un'enorme bomba all'elio. Questo gioiellino ti porterà a ⟦Undercity=Sepulcra⟧ più in fretta e più al sicuro di qualsiasi nave, e la vista toglie davvero il fiato. A proposito di fiato, a bordo dello zeppelin è vietato fumare", "." },
  ["43d0c85e50ef4dc6"] = { "Esattamente quello che pensavo.", "." },
  ["43d0f1da79bcf1aa"] = { "Vorrei comprare un'altra ⟦Elune's Candle=Candela di Elune⟧.", "." },
  ["43d86777bfd306e1"] = { "Il nostro destino ci attende...", "." },
  ["43db7a267f63bdd8"] = { "Dobbiamo concentrarci se vogliamo generare il nostro stormo!", "." },
  ["43e049092393e40a"] = { "Sorgete, servi dell'Incubo! Sorgete e distruggete questo mondo! Che non ci siano sopravvissuti...", "." },
  ["43e8edf00728577b"] = { "%s depone un uovo!", "." },
